# Good! 36 edges, all degree 3. Now verify girth >= 7
from collections import deque

def find_girth(n, edges):
    # Build adjacency list
    adj = defaultdict(set)
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)

    min_cycle = float('inf')

    # BFS from each vertex to find shortest cycle
    for start in range(n):
        # BFS to find shortest cycle through start
        dist = {start: 0}
        parent = {start: -1}
        queue = deque([start])

        while queue:
            node = queue.popleft()
            for neighbor in adj[node]:
                if neighbor not in dist:
                    dist[neighbor] = dist[node] + 1
                    parent[neighbor] = node
                    queue.append(neighbor)
                elif parent[node] != neighbor:
                    # Found a cycle
                    cycle_len = dist[node] + dist[neighbor] + 1
                    min_cycle = min(min_cycle, cycle_len)

    return min_cycle

girth = find_girth(24, edges)
print(f"Girth of the graph: {girth}")
